#!/usr/bin/env bash
# Print up to three client addresses, ordered by request count and then
# by their first occurrence in the log.
set -euo pipefail

script_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)

awk '
NF {
    ip = $1
    if (!(ip in count))
        first[ip] = ++seen
    count[ip]++
}
END {
    for (rank = 1; rank <= 3; rank++) {
        chosen = ""
        for (ip in count) {
            if (ip in printed)
                continue
            if (chosen == "" || count[ip] > count[chosen] ||
                (count[ip] == count[chosen] && first[ip] < first[chosen]))
                chosen = ip
        }
        if (chosen == "")
            break
        print chosen
        printed[chosen] = 1
    }
}
' "$script_dir/access.log"
